<?php
 namespace Pterodactyl\Services\Dezerx; use Pterodactyl\Models\Egg; use Pterodactyl\Models\Server; use Pterodactyl\Services\Dezerx\Catalogue\ModpackCatalogue; class Addons { public const KEY = 'addons'; private static ?array $resolved = null; public const PLAYER_MANAGER = 'player-manager'; public const PLUGIN_MANAGER = 'plugin-manager'; public const MOD_MANAGER = 'mod-manager'; public const MODPACK_MANAGER = 'modpack-manager'; public const VERSION_CHANGER = 'version-changer'; public const PROPERTIES_EDITOR = 'properties-editor'; public const DRIVE_BACKUPS = 'drive-backups'; public const HYTALE_MOD_MANAGER = 'hytale-mod-manager'; public const WORLD_MANAGER = 'world-manager'; public const WORLD_VIEWER = 'world-viewer'; public const FIVEM_UTILS = 'fivem-utils'; public const EGG_SWITCHER = 'egg-switcher'; public const RECYCLE_BIN = 'recycle-bin'; public const SERVER_IMPORTER = 'server-importer'; public const PALWORLD_MOD_MANAGER = 'palworld-mod-manager'; public const AUTO_ACTION = 'auto-action'; public const SECURITY = 'security'; public const DISCORD_BOT = 'discord-bot'; public const ADMIN_OVERVIEW = 'admin-overview'; public const ADMIN_THEME = 'admin-theme'; public const RUST_PLAYER_MANAGER = 'rust-players'; public const RUST_PLUGIN_MANAGER = 'rust-plugins'; public const RUST_WIPE_SCHEDULER = 'rust-wipes'; public const DAYZ_MOD_MANAGER = 'dayz-mods'; public const CATALOGUE = [ self::PLAYER_MANAGER => [ 'name' => 'Player Manager', 'blurb' => 'A Players tab inside a Minecraft server: who has played, their inventory and ender chest, their vitals and statistics, and the moderation actions: op, ban, whitelist, gamemode, heal, kill, teleport, experience.', 'icon' => 'fa-users', ], self::PLUGIN_MANAGER => [ 'name' => 'Plugin Manager', 'blurb' => 'A Plugins tab: browse Modrinth and SpigotMC, install a jar straight into /plugins, and enable, disable or remove what is already there.', 'icon' => 'fa-plug', ], self::MOD_MANAGER => [ 'name' => 'Mod Manager', 'blurb' => 'The same thing for /mods, across Modrinth and CurseForge, over the thirteen loaders Modrinth catalogues: Fabric, Forge, NeoForge, Quilt, Babric, BTA Babric, Java Agent, Legacy Fabric, LiteLoader, Risugami\'s ModLoader, NilLoader, Ornithe and Rift. CurseForge needs an API key.', 'icon' => 'fa-cubes', ], self::MODPACK_MANAGER => [ 'name' => 'Modpack Manager', 'blurb' => 'A Modpacks tab: search Modrinth, FTB, ATLauncher, Technic and CurseForge, and install a server pack onto the server. CurseForge needs an API key.', 'icon' => 'fa-archive', ], self::VERSION_CHANGER => [ 'name' => 'Version Changer', 'blurb' => 'A Version tab: pick server software and a version from MCJars (Paper, Purpur, Fabric, Forge, NeoForge, Velocity and the rest) and have the panel stop the server, install it and set the jar.', 'icon' => 'fa-tags', ], self::PROPERTIES_EDITOR => [ 'name' => 'Server Properties', 'blurb' => 'A Properties tab: server.properties as a typed form rather than a text file, plus the server icon and a one-click Geyser install for Bedrock players.', 'icon' => 'fa-sliders', ], self::HYTALE_MOD_MANAGER => [ 'name' => 'Hytale Mod Manager', 'blurb' => 'A Mods tab for a Hytale server: browse CurseForge\'s Hytale section, install a mod straight onto the server, and enable, disable or remove what is already there. Needs a CurseForge API key; a key set on the Modpack or World manager is reused.', 'icon' => 'fa-cube', ], self::WORLD_MANAGER => [ 'name' => 'World Manager', 'blurb' => 'A Worlds tab in two halves. Browse: CurseForge\'s Minecraft Worlds catalogue, OneBlock, SkyBlock, adventure maps, parkour, as a grid of cards, installed onto the server by the node. Installed: every world already there as a card, with its dimensions, size, seed and version, and switch, archive and delete on each one. Needs a CurseForge API key for the catalogue half; a key set on the Modpack or Hytale manager is reused.', 'icon' => 'fa-globe', ], self::WORLD_VIEWER => [ 'name' => 'World Viewer', 'blurb' => 'A World Viewer tab: installs BlueMap and serves its live 3D map through the panel, plus level.dat as an editable NBT tree and a region grid with a rendered map behind it, down to reading and deleting individual chunks.', 'icon' => 'fa-map', ], self::FIVEM_UTILS => [ 'name' => 'FiveM Utils', 'blurb' => 'A FiveM tab: every Linux artifact build the runtime server publishes, with the recommended and latest ones marked, installed onto the server by the node. Also sets sv_enforceGameBuild in server.cfg and opens txAdmin.', 'icon' => 'fa-cube', 'mark' => '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 48 48" style="vertical-align:-2px" aria-hidden="true"><polygon fill="#ff6f00" points="5,45 9,34 21,22 15,45"/><polygon fill="#ff6f00" points="25,18 33,45 43,45 32,12"/><polygon fill="#ff6f00" points="16.059,14.164 20,3 28,3"/><polygon fill="#ff6f00" points="10.731,29.002 23,17 23,15 11.58,26.667"/><polygon fill="#ff6f00" points="15.142,16.429 13,22 29.724,5.725 28.818,3.178"/><polygon fill="#ff6f00" points="23.932,14.055 24.377,15.626 30.941,9.178 30.385,7.702"/></svg>', ], self::EGG_SWITCHER => [ 'name' => 'Egg Switcher', 'blurb' => 'A Switch tab: the eggs you allow, as cards, and switching to one changes the server\'s egg, its image, its startup command and its variables, then reinstalls it. What a server may switch *to* is a second list on this page.', 'icon' => 'fa-exchange', ], self::RECYCLE_BIN => [ 'name' => 'Recycle Bin', 'blurb' => 'Deleting a file or folder moves it aside instead of destroying it, and a Recycle Bin tab lists what is waiting with how long it has left. Restore one, restore everything, or empty the bin. Anything not restored is deleted for real once the retention period runs out.', 'icon' => 'fa-trash', ], self::SERVER_IMPORTER => [ 'name' => 'Server Importer', 'blurb' => 'An Import tab: copy another server\'s files in over SFTP. People save their own logins, encrypted and private to them, so a host is typed once and reused. Each import picks a source folder, a destination folder and whether to overwrite, replace or leave what is already there, and both the connection and the import itself can be tested before anything is written.', 'icon' => 'fa-download', ], self::PALWORLD_MOD_MANAGER => [ 'name' => 'Palworld Mod Manager', 'blurb' => 'A Mods tab for a Palworld server: browse CurseForge\'s Palworld section, install a mod straight into the pak folder, unpack the ones that arrive as a zip, and enable, disable or remove what is already there. Needs a CurseForge API key; a key set on the Modpack, Mod, World or Hytale manager is reused.', 'icon' => 'fa-paw', ], self::RUST_PLAYER_MANAGER => [ 'name' => 'Rust Player Manager', 'blurb' => 'A Rust Players tab for a Rust server running Oxide or Carbon: the live roster with health, ping and grid, each player\'s inventory, sleeping bags, tool cupboards and blueprints, god tools, bans, server rates, convars and demos. Reads what the RustPlayerBridge companion plugin exports, and installs that plugin for you.', 'icon' => 'fa-users', ], self::RUST_PLUGIN_MANAGER => [ 'name' => 'Rust Plugin Manager', 'blurb' => 'A Rust Plugins tab for a Rust server running Oxide or Carbon: browse and search uMod, install or update a plugin in one click, see which installed plugins have a newer release, and turn them off, reload or remove them.', 'icon' => 'fa-plug', ], self::RUST_WIPE_SCHEDULER => [ 'name' => 'Rust Wipe Scheduler', 'blurb' => 'A Rust Wipes tab for a Rust server: wipe the map, the map and blueprints, or everything on a weekly, fortnightly or monthly schedule (the first Thursday for forced wipes). Players are warned in chat as it gets close, then the server is stopped, wiped, given a new seed if you want one, and started again.', 'icon' => 'fa-calendar', ], self::DAYZ_MOD_MANAGER => [ 'name' => 'DayZ Mod Manager', 'blurb' => 'A DayZ Mods tab for the community DayZ egg: search the Steam Workshop, add a mod and everything it requires in the right order, set load order, choose client or server-side, load mods somebody uploaded, and copy their .bikey files into keys. The server downloads Workshop mods itself when it starts, which needs the host\'s Steam account to own DayZ.', 'icon' => 'fa-crosshairs', 'beta' => true, ], self::SECURITY => [ 'name' => 'Security', 'blurb' => 'Who is allowed to make an account here. Turns away VPNs, proxies and datacentre addresses using proxycheck.io, and refuses a second account from an address one already answers to. An allow list beats both, so nobody locks themselves out.', 'icon' => 'fa-shield', ], self::AUTO_ACTION => [ 'name' => 'Auto Action', 'blurb' => 'A due date on a server and what the panel does when it passes: suspend it, delete it, or force delete it. Set on the admin create-server form and on any server\'s Manage page, and carried out by the panel\'s scheduler.', 'icon' => 'fa-hourglass-end', ], self::DISCORD_BOT => [ 'name' => 'Discord Bot', 'blurb' => 'A Discord bot that works as a remote control for the panel: a server list with game art, a live control panel with the console, power buttons and backups, billing details, connection info, activity, and resource alerts that ping a role when a server runs hot or goes down. Run one bot for everybody, or let each customer bring their own. Built on Discord Components V2 and acting through each person\'s own client API key.', 'icon' => 'fa-comments', 'mark' => '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" style="vertical-align:-2px" aria-hidden="true"><path fill="#5865F2" d="M20.317 4.37a19.79 19.79 0 0 0-4.885-1.515.074.074 0 0 0-.079.037c-.21.375-.444.865-.608 1.25a18.27 18.27 0 0 0-5.487 0 12.64 12.64 0 0 0-.617-1.25.077.077 0 0 0-.079-.037A19.74 19.74 0 0 0 3.677 4.37a.07.07 0 0 0-.032.028C.533 9.046-.32 13.58.099 18.058a.082.082 0 0 0 .031.056 19.9 19.9 0 0 0 5.993 3.03.078.078 0 0 0 .084-.028 14.1 14.1 0 0 0 1.226-1.994.076.076 0 0 0-.041-.106 13.1 13.1 0 0 1-1.872-.892.077.077 0 0 1-.008-.128c.126-.094.252-.192.372-.291a.074.074 0 0 1 .078-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 0 1 .078.009c.12.1.246.198.373.292a.077.077 0 0 1-.006.128 12.3 12.3 0 0 1-1.873.891.077.077 0 0 0-.041.107c.36.698.772 1.363 1.225 1.993a.076.076 0 0 0 .084.029 19.84 19.84 0 0 0 6.002-3.03.077.077 0 0 0 .032-.055c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 0 0-.031-.029zM8.02 15.331c-1.182 0-2.157-1.086-2.157-2.419 0-1.333.956-2.419 2.157-2.419 1.21 0 2.176 1.095 2.157 2.42 0 1.332-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.086-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.095 2.157 2.42 0 1.332-.946 2.418-2.157 2.418z"/></svg>', ], self::ADMIN_OVERVIEW => [ 'name' => 'Admin Overview Extension', 'blurb' => 'Turns the admin home page into an operations view across every node: how many servers are running, offline, suspended or installing, CPU, memory, disk and network over time with the capacity they have to work with, bandwidth used, a table of every node, and the busiest servers by each resource. Filter by node and time range. Usage is sampled once a minute by the panel\'s scheduler, one request per node.', 'icon' => 'fa-area-chart', ], self::ADMIN_THEME => [ 'name' => 'Admin Theme', 'blurb' => 'Draws the admin area with the client panel\'s own look: its accent and colours, light and dark mode, corner radius, card style and font, all read from the theme editor and Appearance settings, so both halves of the panel match. Turning it off puts the stock admin skin straight back.', 'icon' => 'fa-paint-brush', ], self::DRIVE_BACKUPS => [ 'name' => 'Google Drive Backups', 'blurb' => 'Lets a server owner connect their own Google Drive and have backups copied into it on a schedule, keeping only the newest few so the Drive does not fill up. Needs a Google OAuth client.', 'icon' => 'fa-google', ], ]; public const GLOBAL_ADDONS = [ self::AUTO_ACTION, self::SECURITY, self::DISCORD_BOT, self::ADMIN_OVERVIEW, self::ADMIN_THEME, ]; public const EGG_LISTS = [ self::EGG_SWITCHER => [ 'targets' => [ 'label' => 'Eggs people may switch to', 'help' => 'What the tab offers. Tick only eggs that make sense as a swap for the ones above: switching reinstalls the server with the new egg\'s install script, and its files are whatever that script leaves behind. Once there is an egg rule below, the rules decide instead and this list is not used.', ], ], ]; public const EXTRAS = [ self::EGG_SWITCHER => ['switch_startup', 'switch_reinstall', 'switch_wipe'], self::RECYCLE_BIN => ['retention_days'], self::MOD_MANAGER => ['curseforge_key'], self::MODPACK_MANAGER => ['curseforge_key', 'curseforge_base'], self::HYTALE_MOD_MANAGER => ['hytale_directory', 'hytale_extensions', 'curseforge_key'], self::DRIVE_BACKUPS => ['google_client_id', 'google_client_secret'], self::WORLD_MANAGER => ['curseforge_key'], self::PALWORLD_MOD_MANAGER => ['palworld_directory', 'palworld_extensions', 'curseforge_key'], self::DAYZ_MOD_MANAGER => ['steam_api_key'], self::AUTO_ACTION => ['default_action', 'default_term_days', 'grace_minutes'], self::SECURITY => ['block_vpn', 'block_hosting', 'duplicate_ip', 'proxycheck_key', 'ip_allowlist'], self::ADMIN_THEME => [AdminTheme::MODE_KEY, AdminTheme::HINTS_KEY], ]; public static function defaults(): array { return [ self::PLAYER_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::PLUGIN_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::MOD_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::MODPACK_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::VERSION_CHANGER => [ 'enabled' => false, 'eggs' => [], ], self::PROPERTIES_EDITOR => [ 'enabled' => false, 'eggs' => [], ], self::DRIVE_BACKUPS => [ 'enabled' => false, 'eggs' => [], ], self::HYTALE_MOD_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::WORLD_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::WORLD_VIEWER => [ 'enabled' => false, 'eggs' => [], ], self::FIVEM_UTILS => [ 'enabled' => false, 'eggs' => [], ], self::EGG_SWITCHER => [ 'enabled' => false, 'eggs' => [], 'targets' => [], ], self::RECYCLE_BIN => [ 'enabled' => false, 'eggs' => [], ], self::SERVER_IMPORTER => [ 'enabled' => false, 'eggs' => [], ], self::PALWORLD_MOD_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::RUST_PLAYER_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::RUST_PLUGIN_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::RUST_WIPE_SCHEDULER => [ 'enabled' => false, 'eggs' => [], ], self::DAYZ_MOD_MANAGER => [ 'enabled' => false, 'eggs' => [], ], self::AUTO_ACTION => [ 'enabled' => false, 'eggs' => [], ], self::SECURITY => [ 'enabled' => false, 'eggs' => [], ], self::DISCORD_BOT => [ 'enabled' => false, 'eggs' => [], ], self::ADMIN_OVERVIEW => [ 'enabled' => false, 'eggs' => [], ], self::ADMIN_THEME => [ 'enabled' => false, 'eggs' => [], ], ]; } public static function all(): array { if (self::$resolved !== null) { return self::$resolved; } $stored = Settings::get(self::KEY) ?? []; $out = []; foreach (self::defaults() as $addon => $defaults) { $saved = is_array($stored[$addon] ?? null) ? $stored[$addon] : []; $out[$addon] = [ 'enabled' => (bool) ($saved['enabled'] ?? $defaults['enabled']), 'eggs' => array_values(array_filter( array_map('strval', (array) ($saved['eggs'] ?? $defaults['eggs'])), fn (string $uuid) => $uuid !== '', )), ]; foreach (array_keys(self::EGG_LISTS[$addon] ?? []) as $list) { $out[$addon][$list] = array_values(array_filter( array_map('strval', (array) ($saved[$list] ?? [])), fn (string $uuid) => $uuid !== '', )); } foreach (self::EXTRAS[$addon] ?? [] as $extra) { $out[$addon][$extra] = trim((string) ($saved[$extra] ?? '')); } } return self::$resolved = $out; } public static function get(string $addon): array { return self::all()[$addon] ?? ['enabled' => false, 'eggs' => [], 'targets' => []]; } public static function save(string $addon, bool $enabled, array $eggs, array $extras = [], array $lists = []): void { if (!array_key_exists($addon, self::defaults())) { return; } $known = Egg::query()->whereIn('uuid', $eggs)->pluck('uuid')->all(); $entry = [ 'enabled' => $enabled, 'eggs' => array_values(array_unique(array_map('strval', $known))), ]; $current = self::all(); foreach (array_keys(self::EGG_LISTS[$addon] ?? []) as $list) { $entry[$list] = array_key_exists($list, $lists) ? array_values(array_unique(array_map( 'strval', Egg::query()->whereIn('uuid', (array) $lists[$list])->pluck('uuid')->all(), ))) : (array) ($current[$addon][$list] ?? []); } foreach (self::EXTRAS[$addon] ?? [] as $extra) { $entry[$extra] = array_key_exists($extra, $extras) ? trim($extras[$extra]) : (string) ($current[$addon][$extra] ?? ''); } Settings::put(self::KEY, [ ...$current, $addon => $entry, ]); self::$resolved = null; } public static function isGlobal(string $addon): bool { return in_array($addon, self::GLOBAL_ADDONS, true); } public static function scope(string $addon): array { if ($addon === self::EGG_SWITCHER && EggRules::active()) { return EggRules::sources(); } return self::get($addon)['eggs']; } public static function appliesTo(string $addon, Server $server): bool { $config = self::get($addon); $config['eggs'] = self::scope($addon); if (!$config['enabled'] || $config['eggs'] === []) { return false; } $uuid = $server->egg?->uuid; return $uuid !== null && in_array($uuid, $config['eggs'], true); } public static function payload(): array { $payload = []; foreach (self::all() as $addon => $config) { $meta = self::CATALOGUE[$addon] ?? []; $payload[$addon] = [ 'enabled' => $config['enabled'], 'eggs' => self::scope($addon), 'name' => $meta['name'] ?? $addon, 'blurb' => $meta['blurb'] ?? '', 'icon' => $meta['icon'] ?? 'fa-puzzle-piece', 'mark' => $meta['mark'] ?? '', ]; } if ($payload[self::DISCORD_BOT]['enabled'] ?? false) { $payload[self::DISCORD_BOT]['scope'] = \Pterodactyl\Services\Dezerx\DiscordBot\BotConfig::scope(); } if ($payload[self::MODPACK_MANAGER]['enabled'] ?? false) { $payload[self::MODPACK_MANAGER]['sources'] = app(ModpackCatalogue::class)->sources(); } return $payload; } } 